package net.civeira.phylax.features.document.templateversion.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.templateversion.domain.TemplateVersion;
import net.civeira.phylax.features.document.templateversion.domain.event.TemplateVersionEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class TemplateVersionEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<TemplateVersionEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final TemplateVersion entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
